package org.apache.commons.lang3.text;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.apache.commons.lang3.AbstractLangTest;
import org.junit.jupiter.api.Test;

/**
 * Tests {@link StrMatcher#quoteMatcher()}, which matches a single (') or
 * double (") quote character.
 */
@Deprecated
public class StrMatcherTest_testQuoteMatcher extends AbstractLangTest {

    /**
     * A buffer whose final three characters exercise the quote matcher.
     * Reading the characters out by index:
     * <ul>
     *   <li>index 10 = the NUL character (�) - not a quote</li>
     *   <li>index 11 = a single quote (')</li>
     *   <li>index 12 = a double quote (")</li>
     * </ul>
     * (Earlier indices hold assorted digits and whitespace that the quote
     * matcher is never asked about here.)
     */
    private static final char[] BUFFER = "0,1\t2 3\n\r\f�'\"".toCharArray();

    private static final int INDEX_NON_QUOTE = 10;
    private static final int INDEX_SINGLE_QUOTE = 11;
    private static final int INDEX_DOUBLE_QUOTE = 12;

    /** A match consumes one character; a non-match consumes none. */
    private static final int NO_MATCH = 0;
    private static final int ONE_CHAR_MATCH = 1;

    @Test
    void testQuoteMatcher() {
        final StrMatcher matcher = StrMatcher.quoteMatcher();

        // quoteMatcher() returns the same shared, cached instance every time.
        assertSame(matcher, StrMatcher.quoteMatcher());

        assertEquals(NO_MATCH, matcher.isMatch(BUFFER, INDEX_NON_QUOTE));
        assertEquals(ONE_CHAR_MATCH, matcher.isMatch(BUFFER, INDEX_SINGLE_QUOTE));
        assertEquals(ONE_CHAR_MATCH, matcher.isMatch(BUFFER, INDEX_DOUBLE_QUOTE));
    }
}
